raw:
{
  "spells": [
    {
      "id": "spell_faith_01",
      "theory": "旅灯祝福将微量魔力注入受术者随身的一件小物，比如布扣、木牌或绳结，使魔力在物件表面形成一层极薄的安定纹路。纹路随携带者呼吸微微起伏，只缓和慌乱与疲劳感，不驱散野兽、不预警伏击、不改变道路本身。物件离开携带者超过一臂距离，纹路便自行消散，魔力随之散入空气。",
      "casting": "施术者双手合拢包住小物，低声念出受托者的名字或代称，再以拇指沿物件边缘画一道短弧。弧线合拢时魔力送入，物件表面会短暂泛出暖色。",
      "failure": "弧线画得过快或中途停顿，暖色会碎成几点微光后消失，受术者只感到片刻恍惚，随后与未受术时无异。若物件表面有裂纹，魔力可能只停留在裂纹一侧，使祝福时断时续，反而让旅人误以为已经得到持续庇护。",
      "counters": [
        "将受术小物浸入流动河水片刻，安定纹路会被冲散。",
        "用粗盐搓揉物件表面，可磨去附着的魔力痕迹。"
      ],
      "socialConsequences": "乡约见证下的短途出行常请人施此术，受术者会向邻里道谢并留下小物作凭。客栈脚夫和渡口船工乐意接受，因为安定的旅人较少在途中慌张生事。售卖护身符的摊贩会抱怨生意被分走，但也有人转而出售适合承载祝福的空白布扣。若未经同意对他人随身物施术，会被视作侵犯私人物品，引起争执。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时暖色只维持几个呼吸，受术者仍会频繁分心。",
        "熟练后纹路能稳定附着，受术者走完半日路程才感到减弱。",
        "更熟练者可让纹路随呼吸均匀起伏，减少中途消散。",
        "高熟练度下祝福持续到规定时限，仍只缓和情绪，不挡危险。"
      ]
    },
    {
      "id": "spell_faith_02",
      "theory": "病榻守祷把魔力铺展在病人枕边或床沿的织物上，形成一层极薄的舒缓气息。气息不进入身体，也不对抗疾病，只让病人对外界声响与光线不那么敏感，从而更容易入睡。织物被移开或病人离开床铺超过一臂距离，气息便逐渐消散。守祷不替代汤药，也不保证醒后病情好转。",
      "casting": "施术者以手掌轻按床沿织物，从床头向床尾缓慢推出一道掌痕，同时保持呼吸平稳。掌痕推完，织物会微微发凉，表示气息已经铺开。",
      "failure": "推掌时呼吸紊乱，凉意会集中在床角一处，病人仍被另一侧的声响惊醒。若织物有褶皱，气息可能沿褶皱聚成细线，使病人感到局部发冷，反而更难安睡。失败后魔力不会残留成其他效果。",
      "counters": [
        "掀开并抖动床单，可使铺展的舒缓气息散入空中。",
        "在床沿放置一碗清水，水汽会逐渐吸收附着的魔力。"
      ],
      "socialConsequences": "照护病人的家属常请人守祷，尤其在夜间轮换看护时，安睡的病人能让全家得到休息。药铺和游方郎中不反对此术，但会提醒家属它不能代替诊脉与用药。若对不愿接受祈祷的病人强行施术，会被认为不尊重其意愿，可能引发家属间的口角。旅店允许为住客守祷，但要求不得影响邻房。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学掌痕凉意不均，病人仍会因轻微声响醒来。",
        "熟练后气息覆盖整张床铺，病人入睡时间明显缩短。",
        "更熟练者能控制凉意范围，不使床沿以外的人感到不适。",
        "高熟练度下守祷持续到规定时限，仍只助眠，不治疾病。"
      ]
    },
    {
      "id": "spell_faith_03",
      "theory": "净坛术将魔力化作细密的冲刷纹，沿受托祭坛的石面或木面滑过，带走灰尘、蛛网与陈旧的供品残渣。纹路只清理普通污物，不分辨祭品是否合规，也不裁决礼仪争端。魔力在接触污物后迅速消耗，因此一次施术只能覆盖坛面及近旁一小片区域。祭坛若被移走或转作他用，纹路便不再附着。",
      "casting": "施术者以指尖从祭坛中心向外画螺旋，螺旋末端停在坛沿。画线时需保持指尖贴近坛面，画完后坛面会短暂泛出湿意，污物随湿意聚向边缘。",
      "failure": "螺旋画得不匀，湿意会在坛面中央积成一团，只清掉中心一小块，边缘的蛛网与残渣仍在。若坛面有裂缝，魔力可能渗入缝中，使裂缝附近反复泛潮，需要额外擦拭才能恢复干燥。",
      "counters": [
        "用干布沿坛面反向擦拭，可打断尚未完成的冲刷纹。",
        "在坛面撒一层细沙，沙粒会吸收魔力使纹路提前终止。"
      ],
      "socialConsequences": "受托看管祭坛的乡老与庙祝欢迎此术，因为清理工作繁重且容易遗漏边角。售卖香烛与供品的摊贩不担心，祭坛洁净反而吸引更多人来摆放供品。若未经许可对他人看管的祭坛施术，会被视作越权干预，可能被要求当众说明用意。港口的随船祭坛也常请人清理，但须先问明祭坛归属。",
      "law": {
        "river": "consent",
        "city": "consent",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时湿意只覆盖坛面中心，边角污物仍需手工擦除。",
        "熟练后螺旋均匀展开，一次可清理坛面及近旁小片区域。",
        "更熟练者能控制湿意流向，使污物聚向指定一侧便于收走。",
        "高熟练度下清理范围仍限于受托祭坛，不波及其他器物。"
      ]
    }
  ]
}
